import React, { useState, useEffect } from 'react';
import { useHistory, useLocation } from 'react-router-dom';
import { updateCar } from '../../services/ApiCar';

export default function UpdateVoiture() {
  const history = useHistory();
  const location = useLocation();
  const { car: locationCar } = location.state || {};
  const [carId, setCarId] = useState(null);
  
  const [formData, setFormData] = useState({
    matricule: '',
    model: '',
    marque: '',
    libelle: '',
    prix: '',
    prix_jour: '',
    couleur: '',
    disponible: false,
    voiture_image: null
  });
  const [imagePreview, setImagePreview] = useState('');
  const [loading, setLoading] = useState(true);
  const [errors, setErrors] = useState({});

  // Récupérer l'ID depuis l'URL ou le state
  useEffect(() => {
    const pathParts = location.pathname.split('/');
    const idFromUrl = pathParts[pathParts.length - 1];
    setCarId(idFromUrl);
    
    if (locationCar) {
      // Si les données sont passées via le state
      setFormData({
        matricule: locationCar.matricule || '',
        model: locationCar.model || '',
        marque: locationCar.marque || '',
        libelle: locationCar.libelle || '',
        prix: locationCar.prix || '',
        prix_jour: locationCar.prix_jour || '',
        couleur: locationCar.couleur || '',
        disponible: locationCar.disponible || false,
        voiture_image: null
      });
      if (locationCar.voiture_image) {
        setImagePreview(`${process.env.REACT_APP_API_URL}/${locationCar.voiture_image}`);
      }
      setLoading(false);
    } else {
      // Sinon charger depuis l'API
      fetchCarData(idFromUrl);
    }
  }, [location]);

  const fetchCarData = async (id) => {
    try {
      const response = await getCarById(id);
      const car = response.data;
      setFormData({
        matricule: car.matricule,
        model: car.model,
        marque: car.marque,
        libelle: car.libelle,
        prix: car.prix,
        prix_jour: car.prix_jour,
        couleur: car.couleur,
        disponible: car.disponible,
        voiture_image: null
      });
      if (car.voiture_image) {
        setImagePreview(`${process.env.REACT_APP_API_URL}/${car.voiture_image}`);
      }
    } catch (error) {
      console.error("Error fetching car data:", error);
      history.push('/admin/cardvoiture');
    } finally {
      setLoading(false);
    }
  };

  const handleChange = (e) => {
    const { name, value, type, checked } = e.target;
    setFormData({
      ...formData,
      [name]: type === 'checkbox' ? checked : value
    });
  };

  const handleFileChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      setFormData({ ...formData, voiture_image: file });
      setImagePreview(URL.createObjectURL(file));
    }
  };

  const validateForm = () => {
    const newErrors = {};
    if (!formData.matricule.trim()) newErrors.matricule = 'Matricule requis';
    if (!formData.model.trim()) newErrors.model = 'Modèle requis';
    if (!formData.marque.trim()) newErrors.marque = 'Marque requise';
    if (!formData.prix) newErrors.prix = 'Prix requis';
    if (!formData.prix_jour) newErrors.prix_jour = 'Prix par jour requis';
    
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    if (!validateForm()) return;

    try {
      setLoading(true);
      const data = new FormData();
      
      Object.keys(formData).forEach(key => {
        if (formData[key] !== null) {
          data.append(key, formData[key]);
        }
      });

      await updateCar(data, carId);
      history.push('/admin/cardvoiture');
    } catch (error) {
      console.error("Update error:", error);
      alert('Erreur lors de la mise à jour');
    } finally {
      setLoading(false);
    }
  };

  if (loading) {
    return <div className="text-center py-8">Chargement en cours...</div>;
  }

  return (
    <div className="relative flex flex-col min-w-0 break-words w-full mb-6 shadow-lg rounded-lg bg-blueGray-100 border-0">
      <div className="rounded-t bg-white mb-0 px-6 py-6">
        <div className="text-center flex justify-between">
          <h6 className="text-blueGray-700 text-xl font-bold">
            Modifier la voiture {formData.matricule}
          </h6>
          <button
            className="bg-lightBlue-500 text-white font-bold uppercase text-xs px-4 py-2 rounded shadow hover:shadow-md"
            onClick={() => history.push('/admin/Voiture')}
          >
            Retour
          </button>
        </div>
      </div>

      <div className="flex-auto px-4 lg:px-10 py-10 pt-0">
        <form onSubmit={handleSubmit}>
          <h6 className="text-blueGray-400 text-sm mt-3 mb-6 font-bold uppercase">
            Informations du véhicule
          </h6>

          <div className="flex flex-wrap">
            {/* Matricule */}
            <div className="w-full lg:w-6/12 px-4">
              <div className="relative w-full mb-3">
                <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">
                  Matricule
                </label>
                <input
                  type="text"
                  name="matricule"
                  value={formData.matricule}
                  onChange={handleChange}
                  className={`border-0 px-3 py-3 placeholder-blueGray-300 text-blueGray-600 bg-white rounded text-sm shadow focus:outline-none focus:ring w-full ${
                    errors.matricule ? 'border-red-500' : ''
                  }`}
                  placeholder="AA-123-BB"
                />
                {errors.matricule && (
                  <p className="text-red-500 text-xs mt-1">{errors.matricule}</p>
                )}
              </div>
            </div>

            {/* Modèle */}
            <div className="w-full lg:w-6/12 px-4">
              <div className="relative w-full mb-3">
                <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">
                  Modèle
                </label>
                <input
                  type="text"
                  name="model"
                  value={formData.model}
                  onChange={handleChange}
                  className={`border-0 px-3 py-3 placeholder-blueGray-300 text-blueGray-600 bg-white rounded text-sm shadow focus:outline-none focus:ring w-full ${
                    errors.model ? 'border-red-500' : ''
                  }`}
                  placeholder="Clio, 208, etc."
                />
                {errors.model && (
                  <p className="text-red-500 text-xs mt-1">{errors.model}</p>
                )}
              </div>
            </div>

            {/* Marque */}
            <div className="w-full lg:w-6/12 px-4">
              <div className="relative w-full mb-3">
                <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">
                  Marque
                </label>
                <input
                  type="text"
                  name="marque"
                  value={formData.marque}
                  onChange={handleChange}
                  className={`border-0 px-3 py-3 placeholder-blueGray-300 text-blueGray-600 bg-white rounded text-sm shadow focus:outline-none focus:ring w-full ${
                    errors.marque ? 'border-red-500' : ''
                  }`}
                  placeholder="Renault, Peugeot, etc."
                />
                {errors.marque && (
                  <p className="text-red-500 text-xs mt-1">{errors.marque}</p>
                )}
              </div>
            </div>

            {/* Prix par jour */}
            <div className="w-full lg:w-6/12 px-4">
              <div className="relative w-full mb-3">
                <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">
                  Prix/jour (€)
                </label>
                <input
                  type="number"
                  name="prix_jour"
                  value={formData.prix_jour}
                  onChange={handleChange}
                  className={`border-0 px-3 py-3 text-blueGray-600 bg-white rounded text-sm shadow focus:outline-none focus:ring w-full ${
                    errors.prix_jour ? 'border-red-500' : ''
                  }`}
                  placeholder="50"
                  min="0"
                />
                {errors.prix_jour && (
                  <p className="text-red-500 text-xs mt-1">{errors.prix_jour}</p>
                )}
              </div>
            </div>

            {/* Disponibilité */}
            <div className="w-full lg:w-6/12 px-4">
              <div className="relative w-full mb-3">
                <label className="inline-flex items-center mt-3">
                  <input
                    type="checkbox"
                    name="disponible"
                    checked={formData.disponible}
                    onChange={handleChange}
                    className="form-checkbox h-5 w-5 text-lightBlue-600 rounded"
                  />
                  <span className="ml-2 text-blueGray-600 font-bold uppercase text-xs">
                    Disponible
                  </span>
                </label>
              </div>
            </div>

            {/* Image */}
            <div className="w-full px-4">
              <div className="relative w-full mb-3">
                <label className="block uppercase text-blueGray-600 text-xs font-bold mb-2">
                  Photo du véhicule
                </label>
                {imagePreview && (
                  <div className="mb-4">
                    <img 
                      src={imagePreview} 
                      alt="Preview" 
                      className="h-40 object-contain rounded"
                    />
                  </div>
                )}
                <input
                  type="file"
                  name="voiture_image"
                  onChange={handleFileChange}
                  className="border-0 px-3 py-3 text-blueGray-600 bg-white rounded text-sm shadow focus:outline-none focus:ring w-full"
                  accept="image/*"
                />
              </div>
            </div>
          </div>

          <div className="text-center mt-6">
            <button
              type="submit"
              disabled={loading}
              className={`${
                loading ? 'bg-gray-500' : 'bg-lightBlue-500 hover:bg-lightBlue-600'
              } text-white font-bold uppercase text-xs px-6 py-3 rounded shadow hover:shadow-md outline-none focus:outline-none mr-1 ease-linear transition-all duration-150`}
            >
              {loading ? 'Enregistrement...' : 'Mettre à jour'}
            </button>
          </div>
        </form>
      </div>
    </div>
  );
}
